});

const apply = () => {
  const q = box.value.trim().toLowerCase();
  morse.$$("div.tbl > div.sc > table > tbody > tr").forEach(tr => {
    tr.classList.toggle("morse-hide", q !== "" && !tr.textContent.toLowerCase().includes(q));
  });
};

morse.watch("div.tbl > h3", h => {
  if (h.nextElementSibling !== box) h.after(box);
});

morse.on(box, "input", apply);

