morse.on(document, "keydown", e => {
  if (e.metaKey || e.ctrlKey || e.altKey) return;
  const t = e.target;
  if (t && (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName))) return;
  const key = e.key.toLowerCase();
  if (key !== "j" && key !== "k") return;
  const rows = morse.$$('[role="option"][data-i]');
  if (!rows.length) return;
  const current = rows.findIndex(r => r.getAttribute("aria-selected") === "true");
  const i = key === "j"
    ? Math.min(rows.length - 1, current + 1)
    : Math.max(0, current < 0 ? 0 : current - 1);
  const next = rows[i];
  rows.forEach(r => r.setAttribute("aria-selected", r === next ? "true" : "false"));
  next.click();
  next.scrollIntoView({ block: "nearest" });
  e.preventDefault();
});

morse.on(document, "keydown", e => {
  if (e.ctrlKey || e.metaKey || e.altKey) return;
  const k = e.key.toLowerCase();
  if (k !== "j" && k !== "k") return;
  const t = e.target;
  if (t && (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName))) return;
  const rows = morse.$$('div.r9[role="option"]');
  if (!rows.length) return;
  let i = rows.findIndex(r => r.getAttribute("aria-selected") === "true");
  i = k === "j" ? Math.min(rows.length - 1, i + 1) : Math.max(0, i < 0 ? 0 : i - 1);
  e.preventDefault();
  rows[i].click();
  rows[i].scrollIntoView({ block: "nearest" });
});

morse.on(document, "keydown", e => {
